package cl.robermotos.delivery.adapter;
import cl.robermotos.delivery.dto.*; import cl.robermotos.delivery.service.Geo; import java.util.UUID;
public abstract class AbstractMockAdapter implements DeliveryProviderAdapter { protected abstract long base(); protected abstract long perKm(); protected abstract int etaBase(); public DeliveryQuoteDTO quote(DeliveryRequest r){ pause(); double km=Geo.haversine(r.pickupLat(),r.pickupLng(),r.dropoffLat(),r.dropoffLng()); return new DeliveryQuoteDTO(provider(),displayName(),Geo.ceilTen(base()+perKm()*km),etaBase()+(int)Math.ceil(km*3),Math.round(km*100.0)/100.0,UUID.randomUUID().toString()); } public DispatchResult dispatch(String orderId,DeliveryRequest r,String quoteId){return new DispatchResult(provider(),"MOCK-"+UUID.randomUUID(),orderId,"BUSCANDO_REPARTIDOR");} private void pause(){try{Thread.sleep(300+(long)(Math.random()*401));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}} }